"lutins-paccots":{"rev":"d2e65f78b5c16c9ee9f92cf2c09f22ee3d2659907cdeecbac9c0f88b29722571","strings":{"name":"Sentier des Lutins · promenade en forêt","intro":"Un court parcours thématique dans la forêt des Paccots.","parentDetails":"Promenade libre avec un adulte.","age":"Promenade en famille ; pour les jeunes enfants, évaluez la montée et le portage.","schedule":"Toute l’année ; les décorations et le conte de fées changent selon la saison.","price":"Le coût de l’accès n’est pas indiqué.","address":"Départ parking Les Rosalys, Route des Dailles, 1619 Les Paccots","notes[0]":"Sentier forestier d’environ 1 km et 30 minutes depuis le parking Les Rosalys ou Vérollys ; il peut se faire en aller-retour ou en boucle.","notes[1]":"Le parcours ne convient pas aux poussettes ni aux personnes à mobilité réduite ; la montée est d’environ 90 m. Un petit enfant peut devoir être porté.","notes[2]":"À ne pas confondre avec l’espace de loisirs des Paccots, qui est en rénovation en automne 2026.","practical.indoor.text":"Sentier forestier en plein air","practical.access.text":"Ne convient pas aux poussettes","practical.duration.text":"Environ 30 minutes et 1 km","practical.warnings[0]":"Montée d’environ 90 m ; un petit enfant peut devoir être porté","research.findings[0].field":"Sentier","research.findings[0].text":"Parcours forestier thématique ouvert toute l’année, d’environ 1 km et 30 minutes, avec une montée de 90 m ; ne convient pas aux poussettes.","research.remaining[0]":"Le coût de l’accès n’est pas indiqué ; vérifiez l’état du sentier avant la sortie.","contacts[0].name":"Les Paccots Tourisme","sources[0].label":"Longueur, montée, parcours, parking et restriction pour les poussettes"}},
"maison-cailler-broc":{"rev":"f394eee252344c293090ebbeba946a141adca7efdf72c045fdc1db4fdbb1480d","strings":{"name":"Maison Cailler · visite en famille","intro":"Une visite sur le chocolat avec dégustation ; une visite en famille, pas un cours éducatif.","parentDetails":"L’enfant parcourt l’exposition avec un adulte.","age":"Gratuit de 0 à 5 ans ; pas d’âge minimum formel","schedule":"Tous les jours 10–18 jusqu’au 31.10 ; 10–17 dès le 01.11 ; dernière entrée une heure avant la fermeture","price":"Adulte CHF 17 ; 0–5 ans gratuit ; 6–15 ans CHF 7","address":"Rue Jules Bellet 7, 1636 Broc","notes[0]":"Un parcours sur le chocolat, la production et la dégustation ; pour les jeunes enfants, le format est plutôt une visite en famille qu’une activité.","notes[1]":"Des versions audio sont disponibles, notamment en allemand, en français et en anglais ; ce ne sont pas des langues d’accompagnement personnel.","notes[2]":"Fermé le 25 décembre et le 1er janvier ; les horaires des jours fériés peuvent différer. Il vaut mieux vérifier à l’avance un billet pour une heure précise.","practical.indoor.text":"Excursion en intérieur, exposition","practical.booking.text":"Vérifier s’il y a un créneau libre avant la sortie","practical.costNote.text":"Un adulte avec un jeune enfant : CHF 17 selon les prix publiés par âge","research.findings[0].field":"Billet famille","research.findings[0].text":"L’entrée est gratuite pour les enfants de 0 à 5 ans, un billet adulte coûte CHF 17 ; le parcours est ouvert tous les jours, avec des heures de fermeture saisonnières.","research.remaining[0]":"Avant la sortie, vérifier s’il y a un créneau libre et les horaires des jours fériés.","contacts[0].name":"Maison Cailler","sources[0].label":"Tourisme : prix par âge, horaires, adresse et langues"}},
"maison-gruyere-pringy":{"rev":"de108500aedd5f25c14105101e748e9e3f806b5be57fadc986a416252c160045","strings":{"name":"La Maison du Gruyère · fromagerie","intro":"Observation de la fabrication du fromage et courte exposition audio.","parentDetails":"L’enfant visite l’exposition avec un adulte.","age":"Visite en famille ; les enfants jusqu’à 12 ans sont inclus dans le billet famille","schedule":"Tous les jours 09–18:30 jusqu’au 30.09 ; ensuite, les horaires changent selon la saison","price":"Adulte CHF 8 ; billet famille pour 2 adultes + enfants jusqu’à 12 ans CHF 12","address":"Place de la Gare 3, 1663 Pringy","notes[0]":"Exposition libre d’environ 30–45 minutes avec audio. La fabrication du fromage peut être observée principalement de 09:00 à 12:30, 2–4 fois par jour selon la saison.","notes[1]":"Dernière entrée 30 minutes avant la fermeture. La source n’indique pas de prix séparé pour les enfants de moins de 12 ans ; un forfait famille est indiqué.","notes[2]":"Vérifiez l’horaire de production et les horaires après septembre le jour de la sortie.","practical.indoor.text":"L’exposition et la fromagerie sont à l’intérieur","practical.duration.text":"La visite de l’exposition dure environ 30–45 minutes","practical.costNote.text":"Un billet famille de CHF 12 est publié pour deux adultes et les enfants jusqu’à 12 ans","research.findings[0].field":"Observation de la production","research.findings[0].text":"La fabrication du fromage est montrée principalement entre 09:00 et 12:30, 2–4 fois par jour ; l’exposition dure environ 30–45 minutes.","research.remaining[0]":"Vérifiez les horaires le jour choisi et le tarif famille si la famille ne compte pas 2 adultes.","contacts[0].name":"La Maison du Gruyère","sources[0].label":"Tourisme : prix, horaires saisonniers et production"}},
