"murten-family-pool":{"rev":"67665ff2179025df7c1367bb08b832de3503ff0fd5caebdc50bc63764bda22eb","strings":{"name":"Piscine de Morat · natation en famille","intro":"Piscine couverte pour des visites libres avec un enfant ; la piscine de jeux est indiquée sans profondeur.","age":"Les limites d’âge ne sont pas publiées","schedule":"lun. 14:00–21:00 ; mar. 06:00–21:00 ; mer.–ven. 09:30–21:00 ; sam.–dim. 09:30–18:00","price":"Adulte CHF 8 ; enfant de 6–15 ans CHF 5 ; jusqu’à 6 ans, renseignez-vous auprès de l’organisateur","address":"Lausannestrasse 2, 3280 Murten","notes[0]":"Il s’agit d’une simple visite en famille sans moniteur ni monitrice, distincte des cours Baby Bade-Plausch et First Flow.","notes[1]":"La plage, l’espace extérieur et le café sont saisonniers ; les heures d’ouverture de la piscine couverte ne garantissent pas qu’ils soient ouverts.","practical.indoor.text":"La piscine couverte de Murten est ouverte toute l’année ; la page touristique décrit un bassin de jeux à l’eau chaude.","practical.warnings[0]":"La profondeur de la piscine de jeux et le billet pour un enfant de moins de six ans ne sont pas indiqués.","research.findings[0].field":"Disponibilité et format","research.findings[0].text":"La piscine couverte de Murten est ouverte toute l’année ; la page touristique décrit un bassin de jeux à l’eau chaude.","research.remaining[0]":"La profondeur de la piscine de jeux et le billet pour un enfant de moins de six ans ne sont pas indiqués.","contacts[0].name":"Schwimmbad Murten","sources[0].label":"Piscine, espace famille, adresse, horaires et tarif"}},
"musee-grenouilles-estavayer":{"rev":"92691e3ebb29e761d3c8b867b905da9f638de47fc355db4fb40dc14472016b23","strings":{"name":"Musée des Grenouilles · visite en famille","intro":"Un petit musée avec l’histoire d’Estavayer et une collection inhabituelle de grenouilles.","parentDetails":"L’enfant visite le musée avec un adulte.","age":"Musée familial ; tarif enfant, âge minimum non indiqué","schedule":"Mars–décembre : mar.–dim. 13–18 ; fermé janvier–février","price":"Adulte CHF 5 ; enfant CHF 3 (âge minimum non indiqué)","address":"Rue du Musée 13, 1470 Estavayer-le-Lac","notes[0]":"Une partie bien connue de l’exposition présente des grenouilles naturalisées dans des scènes. Les parents devraient évaluer le contenu au préalable pour un enfant sensible.","notes[1]":"Fermé en janvier–février, ainsi que les 25, 26 et 31 décembre.","notes[2]":"Il s’agit d’une visite de musée, pas d’un atelier pour enfants.","practical.indoor.text":"Musée en intérieur","practical.warnings[0]":"L’exposition comprend des animaux naturalisés ; évaluer si cela convient à l’enfant","practical.warnings[1]":"Fermé en janvier et février","research.findings[0].field":"Exposition","research.findings[0].text":"Les pièces exposées comprennent des scènes faites de grenouilles naturalisées ; entrée adulte CHF 5, enfant CHF 3.","research.remaining[0]":"L’âge minimum pour le billet enfant n’est pas indiqué ; une famille avec un enfant sensible devrait évaluer l’exposition au préalable.","contacts[0].name":"Musée d’Estavayer","sources[0].label":"Exposition, tarif, horaires et contact"}},
"museum":{"rev":"ef33f2b25c889d60dbd87568ba1457306fa5b29b35d1861d9687ee88c7f532c6","strings":{"name":"Musée d’histoire naturelle · ateliers en famille","intro":"Atelier en famille avec des médiateurs et médiatrices du musée et des spécialistes de l’AEF.","age":"Recommandé pour les enfants de 3–7 ans ; les enfants plus jeunes et plus âgés sont admis","schedule":"samedi · 09:30–10:30 ou 10:45–11:45","price":"Gratuit","address":"Chemin du Musée 6, Fribourg","notes[0]":"Deux séances séparées, pas une longue activité. L’inscription est obligatoire. Vérifiez la langue de la séance concernée.","practical.indoor.text":"Rendez-vous au musée","practical.booking.text":"Inscription par téléphone au 026 305 89 00","practical.duration.text":"Une séance, 60 minutes","practical.commitment.text":"Séances gratuites séparées","research.findings[0].field":"Pour les jeunes enfants","research.findings[0].text":"Les âges de 3–7 ans sont recommandés, mais les enfants plus jeunes et plus âgés sont expressément admis. Les activités sont animées par des médiateurs et médiatrices du musée avec des spécialistes de l’AEF. Gratuit, inscription au 026 305 89 00 ; rendez-vous à l’accueil exactement au début de la séance choisie.","research.remaining[0]":"Places disponibles, langue et possibilité de départ anticipé : à discuter lors de l’inscription.","contacts[0].name":"Musée","sources[0].label":"Source officielle"}},
"nant-beach":{"rev":"d06b7e2b17269c127a8a567ab811c9a008a0f24cf98689392520565773f1ba7a","strings":{"name":"Plage de Nant · place de jeux au bord du lac","intro":"Plage publique avec une place de jeux pour enfants et un espace barbecue.","age":"Limites d’âge non publiées","schedule":"Plage publique ; les services sont saisonniers","price":"Prix non publié","address":"Plage de Nant, 1786 Nant","notes[0]":"Les terrains de football et de volleyball ne sont pas un espace pour les jeunes enfants.","notes[1]":"Vérifiez sur place la disponibilité saisonnière des installations au bord de l’eau et l’accès à l’eau.","practical.indoor.text":"Plage publique en contrebas de l’école de Nant avec une place de jeux pour enfants et un espace barbecue.","practical.warnings[0]":"Les toilettes, l’ombre, le tarif du parking et les heures d’ouverture de la buvette ne sont pas indiqués.","research.findings[0].field":"Disponibilité et format","research.findings[0].text":"Plage publique en contrebas de l’école de Nant avec une place de jeux pour enfants et un espace barbecue.","research.remaining[0]":"Les toilettes, l’ombre, le tarif du parking et les heures d’ouverture de la buvette ne sont pas indiqués.","contacts[0].name":"Vully Tourisme","sources[0].label":"Plage, place de jeux et contact"}},
"ne-pour-lire-estavayer":{"rev":"72aeb9004267ff42f104800f77622c4f77e5d40cba8fb7e18872212451bb9342","strings":{"name":"Né pour lire · bibliothèque d’Estavayer","intro":"Livres, histoires et conversation avec un jeune enfant, avec un adulte, à la bibliothèque.","parentDetails":"Un parent ou un autre adulte participe avec l’enfant.","age":"0–4 ans","schedule":"5 octobre, 11 novembre, 10 décembre 2026 · 09:30–11:00","price":"Prix non publié","address":"Route de la Chapelle 33, 1470 Estavayer-le-Lac","notes[0]":"Trois séances sont publiées séparément ; la régularité entre elles n’est pas supposée.","notes[1]":"L’âge de 0–4 ans et la participation d’un adulte sont indiqués par la bibliothèque. Le prix et la langue de la personne qui anime chaque séance ne sont pas publiés.","notes[2]":"L’inscription se fait par le formulaire de la page de la bibliothèque ; la disponibilité des places doit y être vérifiée avant le déplacement.","practical.indoor.text":"La séance a lieu à l’intérieur, dans la bibliothèque.","practical.booking.text":"Le site de la bibliothèque propose un formulaire d’inscription avec choix de la date.","research.findings[0].field":"Dates, âge et inscription","research.findings[0].text":"La page actuelle de la bibliothèque publie les 5 octobre, 11 novembre et 10 décembre 2026, 09:30–11:00, pour les enfants de 0–4 ans avec un parent, et propose un formulaire d’inscription pour une date précise.","research.findings[1].field":"Adresse et contact","research.findings[1].text":"La bibliothèque se trouve à la Route de la Chapelle 33, Estavayer-le-Lac ; téléphone 026 663 95 08.","research.remaining[0]":"Vérifier la disponibilité des places, le coût et la langue de la séance concernée.","contacts[0].name":"Bibliothèque publique d’Estavayer","sources[0].label":"Bibliothèque : âge, dates et formulaire d’inscription","sources[1].label":"Bibliothèque : adresse et téléphone","sources[2].label":"AEF : programme et horaires"}},
