"psymolo-theatre":{"rev":"667ee225f0b2d4c4f29799b6f103eb150221d02a85636b0dd65725b3e983ac75","strings":{"name":"Théâtre PSYMOLO","age":"Vérifier l’âge.","schedule":"Vérifier les horaires.","price":"Prix non publié.","notes[0]":"L’annuaire indique l’âge de 3–5 ans. Il ne s’agit pas de la gymnastique commune pour les 0–3 ans. La participation constante d’un parent n’est pas confirmée.","sources[0].label":"Source officielle"}},
"psymolo":{"rev":"f70a47ee6e9e22a0287359654bd2b75ee06aaf9c826b1fafcae2ff47c8970c8f","strings":{"name":"PSYMOLO · gym parent-enfant","age":"0–3 ans","schedule":"Horaires à confirmer","price":"Prix non publié","address":"Cabinet PSYMOLO, Route de Fribourg 15, Marly","notes[0]":"L’âge est indiqué dans l’annuaire communal. Vérifiez le groupe actuel destiné spécifiquement aux jeunes enfants, les horaires, le prix et la taille du groupe.","research.findings[0].field":"Format et contact","research.findings[0].text":"Sur son site actuel, le cabinet propose des séances pour des enfants avec leurs parents et publie une personne de contact à la Route de Fribourg 15. Le groupe actuel pour jeunes enfants, les horaires et le prix ne sont pas publiés.","research.remaining[0]":"Séances actuelles destinées spécifiquement aux jeunes enfants, horaires, prix, nombre de participants. Le fait que le site soit indisponible ne signifie pas que le cabinet a fermé ; le contact de l’annuaire communal a été conservé.","sources[0].label":"Source officielle","sources[1].label":"Annuaire de Marly 2026","sources[2].label":"Vérification complémentaire : Format et contact"}},
"ptites-bottes-family-visit":{"rev":"de9fc36588f330c099538dafa6144366baf8f74a5f7edbb5a4779c391d22c7ae","strings":{"name":"Aux P’tites Bottes · visite en famille à la ferme","intro":"Une heure individuelle à la ferme avec un parent, les animaux et une éventuelle courte balade à poney.","age":"Sur la page principale, les séances individuelles avec un parent sont indiquées pour les âges de 6 mois à 12 ans.","schedule":"Du lundi au samedi sur rendez-vous individuel ; les créneaux publiés peuvent ne plus être à jour.","price":"CHF 50 par visite d’1 heure ; à partir du troisième enfant +CHF 20.","address":"Ferme pédagogique Aux P’tites Bottes, 1678 Siviriez","notes[0]":"Pendant la visite, il est possible de rencontrer des poneys, des chevaux, des vaches, des chèvres, des poules et des lapins ; la balade à poney est facultative.","notes[1]":"Le tarif est celui de la visite, avec un supplément à partir de trois enfants, et non par personne ; il n’y a pas d’inscription en ligne.","practical.indoor.text":"L’organisateur propose une visite individuelle en famille d’une heure auprès des animaux pour CHF 50 ; l’enfant peut faire une balade à poney s’il le souhaite.","practical.warnings[0]":"L’adresse exacte de la ferme et les dates disponibles sont à convenir ; le calendrier du site web n’est publié que jusqu’en mai 2026.","research.findings[0].field":"Disponibilité et format","research.findings[0].text":"L’organisateur propose une visite individuelle en famille d’une heure auprès des animaux pour CHF 50 ; l’enfant peut faire une balade à poney s’il le souhaite.","research.remaining[0]":"L’adresse exacte de la ferme et les dates disponibles sont à convenir ; le calendrier du site web n’est publié que jusqu’en mai 2026.","sources[0].label":"Organisateur : contenu, durée, prix et inscription","sources[1].label":"Organisateur : âge pour le format individuel","sources[2].label":"Contact et jours sur rendez-vous"}},
"ptites-bottes-mamans":{"rev":"5b61811269c94cbe4e78f25dfba530429016ac36e046a277ba7f02ccba1b33ea","strings":{"name":"Aux P’tites Bottes · rencontre pour mères avec enfants","intro":"Une rencontre privée pour mères et enfants dès 2 ans dans une ferme ; la date est convenue individuellement.","age":"Dès 2 ans ; limite supérieure non indiquée","schedule":"Sur rendez-vous, lun.–sam. ; pas de dates fixes","price":"CHF 20 par mère pour 1 heure 15 minutes ; après deux enfants, +CHF 5 par enfant","address":"Ferme pédagogique Aux P’tites Bottes, 1678 Siviriez","notes[0]":"Ce format s’adresse à un groupe de mères : café ou thé pour les adultes et, pour les enfants, rencontre avec les animaux et soins aux animaux.","notes[1]":"Le prix de CHF 20 est indiqué par mère. Le supplément de CHF 5 s’applique seulement après deux enfants. L’inscription se fait par lettre ou par téléphone.","practical.indoor.text":"L’organisateur propose une rencontre privée pour mères avec enfants dès 2 ans, d’une durée de 1 heure 15 minutes, avec échanges et activités avec les animaux.","practical.warnings[0]":"Le groupe, la date et l’adresse exacte doivent être convenus ; ce format n’est pas une rencontre régulière ouverte.","research.findings[0].field":"Disponibilité et format","research.findings[0].text":"L’organisateur propose une rencontre privée pour mères avec enfants dès 2 ans, d’une durée de 1 heure 15 minutes, avec échanges et activités avec les animaux.","research.remaining[0]":"Le groupe, la date et l’adresse exacte doivent être convenus ; ce format n’est pas une rencontre régulière ouverte.","sources[0].label":"Organisateur : format, âge, horaire et prix","sources[1].label":"Contact et inscription"}},
